import { expect, test, type Page } from '@playwright/test'
import { APP_URL, blockRemoteFonts, openDatabaseNode } from './helpers'

// Concrete performance test for the result panel with a REAL 1,000,000-row result
// (generated by the `perf_rows_<N>` demo hook — an actual array of 1M row objects
// flowing through the real render path, not a mock/screenshot).
//
// We measure two things per action, both objective:
//   • maxTask — the longest main-thread long-task (>50ms) the browser reported
//     during the action. This IS the freeze the user feels; a laggy JSON build
//     shows up here as hundreds of ms.
//   • wall    — wall-clock from click until the view's content is on screen.
//
// Hard budgets (assertions) below. Switching between Grid/JSON/Single Row/Chart on
// 1M rows must not block the main thread beyond SWITCH_BUDGET_MS.
// Observed on the dev machine at 1M rows: json ~180ms, chart ~65ms, grid/single ~0ms
// (chart was ~3546ms before the fix). Budget = 800ms leaves headroom for slower CI
// while still failing hard on the multi-second freeze class this guards against.
const SWITCH_BUDGET_MS = 800
const LOAD_BUDGET_MS = 6000 // generating + first paint of 1M rows (one-off)

async function reset(page: Page) {
  await page.evaluate(() => ((window as typeof window & { __perf?: { tasks: number[] } }).__perf!.tasks = []))
}
async function maxTask(page: Page): Promise<number> {
  // let the long-task observer flush the tasks from the action just performed
  await page.waitForTimeout(350)
  return page.evaluate(() => {
    const t = (window as typeof window & { __perf?: { tasks: number[] } }).__perf!.tasks
    return t.length ? Math.max(...t) : 0
  })
}

test('result views stay responsive with 1,000,000 rows', async ({ page }) => {
  test.setTimeout(180_000)
  const results: Record<string, { wall: number; maxTask: number }> = {}
  const errors: string[] = []
  page.on('pageerror', (e) => errors.push(String(e)))

  // install the long-task observer before any app script runs
  await page.addInitScript(() => {
    const w = window as typeof window & { __perf?: { tasks: number[] } }
    w.__perf = { tasks: [] }
    try {
      const obs = new PerformanceObserver((list) => {
        for (const e of list.getEntries()) w.__perf!.tasks.push(e.duration)
      })
      obs.observe({ entryTypes: ['longtask'] })
    } catch {
      /* longtask unsupported → maxTask stays 0, wall still asserted */
    }
  })

  await blockRemoteFonts(page)
  await page.goto(APP_URL)
  await page.waitForSelector('#app > *', { timeout: 15_000 })
  await page.waitForTimeout(300)

  await page.getByRole('button', { name: /Postgres/ }).first().click()
  await page.waitForTimeout(200)
  await openDatabaseNode(page)
  await page.getByTitle('New SQL tab (Ctrl+T)').first().click()
  await page.waitForTimeout(200)

  // load 1,000,000 real rows
  await page.locator('.cm-content').first().click()
  await page.keyboard.type('SELECT * FROM perf_rows_1000000')
  await page.keyboard.press('Escape') // dismiss autocomplete
  await reset(page)
  let t0 = Date.now()
  await page.getByRole('button', { name: 'Run' }).first().click()
  const gridSummary = page.getByText(/Rows 1–200 of 1,000,000/)
  await expect(gridSummary).toBeVisible({ timeout: 60_000 })
  results.load = { wall: Date.now() - t0, maxTask: await maxTask(page) }

  // Grid → JSON (the historically slow one)
  await reset(page)
  t0 = Date.now()
  await page.getByRole('button', { name: 'JSON', exact: true }).click()
  await expect(page.locator('pre.mono.selectable')).toBeVisible({ timeout: 30_000 })
  await expect(page.getByText('Showing first 2,000 of 1,000,000 rows')).toBeVisible()
  results.json = { wall: Date.now() - t0, maxTask: await maxTask(page) }

  // JSON → Single Row
  await reset(page)
  t0 = Date.now()
  await page.getByRole('button', { name: 'Single Row', exact: true }).click()
  await expect(page.getByText('Row', { exact: true })).toBeVisible({ timeout: 30_000 })
  results.single = { wall: Date.now() - t0, maxTask: await maxTask(page) }

  // Single Row → Chart (aggregates over all rows)
  await reset(page)
  t0 = Date.now()
  await page.getByRole('button', { name: 'Chart', exact: true }).click()
  await expect(page.getByText('Chart Builder')).toBeVisible({ timeout: 30_000 })
  results.chart = { wall: Date.now() - t0, maxTask: await maxTask(page) }

  // Chart → Grid
  await reset(page)
  t0 = Date.now()
  await page.getByRole('button', { name: 'Grid', exact: true }).click()
  await expect(gridSummary).toBeVisible({ timeout: 30_000 })
  results.gridBack = { wall: Date.now() - t0, maxTask: await maxTask(page) }

  // report the concrete numbers
  const report = Object.entries(results)
    .map(([k, v]) => `  ${k.padEnd(9)} wall=${v.wall}ms  maxTask=${Math.round(v.maxTask)}ms`)
    .join('\n')
  console.log(`\n[perf 1,000,000 rows]\n${report}\n`)

  // no crashes
  expect(errors, `page errors: ${errors.join('\n')}`).toEqual([])
  // load is a one-off; give it a wider budget
  expect(results.load.maxTask, 'initial 1M load main-thread block').toBeLessThan(LOAD_BUDGET_MS)
  // every view switch must stay responsive
  for (const k of ['json', 'single', 'chart', 'gridBack'] as const) {
    expect(results[k].maxTask, `${k} switch main-thread block`).toBeLessThan(SWITCH_BUDGET_MS)
    expect(results[k].wall, `${k} switch wall-clock`).toBeLessThan(SWITCH_BUDGET_MS + 1500)
  }
})
